use serde_json::{Value, from_str, to_value};
use std::str::FromStr;

pub fn solve(input: Value) -> Value {
    if let Some(hex_str) = input.as_str() {
        if hex_str.len() % 2 == 0 {
            let bytes = hex_str
                .chars()
                .collect::<Vec<_>>()
                .chunks(2)
                .map(|chunk| {
                    let byte = u8::from_str_radix(&chunk.iter().collect::<String>(), 16);
                    byte.ok().unwrap_or(0)
                })
                .collect::<Vec<_>>();
            if bytes.len() <= 128 {
                return to_value(bytes).unwrap();
            }
        }
    }
    to_value(&null).unwrap()
}
